def get_1password_credentials(vault_id, fields, item_id=None, item_title=None, request_id=None, **_extra):
    import json, os, datetime, time, secrets, hashlib, re

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0150000" if __import__("os").path.isdir("./environment_mix/0150000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now_dt = datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0)
    now_iso = now_dt.isoformat()

    # ---- input validation ----
    if not isinstance(vault_id, str) or not vault_id.strip():
        return _err("VALIDATION_ERROR", "vault_id must be a non-empty string")
    vault_id = vault_id.strip()

    allowed_field_values = {"username", "password", "url", "totp", "notes", "custom_fields"}
    if not isinstance(fields, list) or len(fields) < 1:
        return _err("VALIDATION_ERROR", "fields must be a non-empty array")
    req_fields = []
    seen = set()
    for f in fields:
        if not isinstance(f, str):
            return _err("VALIDATION_ERROR", "fields entries must be strings")
        if f not in allowed_field_values:
            return _err("VALIDATION_ERROR", "fields contains an invalid value", field=f)
        if f not in seen:
            seen.add(f)
            req_fields.append(f)

    if item_id is not None:
        if not isinstance(item_id, str) or not item_id.strip():
            return _err("VALIDATION_ERROR", "item_id must be a non-empty string when provided")
        item_id = item_id.strip()
    if item_title is not None:
        if not isinstance(item_title, str) or not item_title.strip():
            return _err("VALIDATION_ERROR", "item_title must be a non-empty string when provided")
        item_title = item_title.strip()

    if request_id is None:
        request_id = f"req_{secrets.token_hex(16)}"
    if not isinstance(request_id, str) or not request_id.strip():
        return _err("VALIDATION_ERROR", "request_id must be a non-empty string when provided")
    request_id = request_id.strip()

    def _parse_dt(s):
        if s is None:
            return None
        if isinstance(s, datetime.datetime):
            return s
        if not isinstance(s, str):
            return None
        ss = s.strip()
        if ss.endswith("Z"):
            ss = ss[:-1] + "+00:00"
        try:
            return datetime.datetime.fromisoformat(ss)
        except Exception:
            return None

    def _gen_id(prefix):
        # try to resemble sample ids: op[a|p|s]_ + uppercase base32-ish token
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        token = "".join(secrets.choice(alphabet) for _ in range(26))
        return f"{prefix}_01{token}"

    def _match_title(expr, title):
        if expr is None or title is None:
            return False
        if not isinstance(expr, str) or not isinstance(title, str):
            return False
        expr_s = expr.strip()
        title_s = title.strip()
        if not expr_s or not title_s:
            return False
        # regex-like if common metacharacters; otherwise substring match case-insensitive
        use_regex = any(ch in expr_s for ch in ["^", "$", ".*", "(", ")", "[", "]", "{", "}", "\\", "|", "?","+"])
        if use_regex:
            try:
                return re.search(expr_s, title_s) is not None
            except re.error:
                return False
        return expr_s.lower() in title_s.lower()

    # ---- load store ----
    clients = _load("api_clients.json")
    policies = _load("credential_policies.json")
    sessions = _load("retrieval_sessions.json")
    audits = _load("retrieval_audit_logs.json")

    # ---- ambient authentication: find a workable active client (no api_key param in this tool) ----
    # Choose an active client that has at least one active allow policy (system can serve the request).
    client = None
    for c in clients:
        if not isinstance(c, dict):
            continue
        if c.get("status") != "active":
            continue
        cid = c.get("id")
        if not cid:
            continue
        has_allow = False
        for p in policies:
            if not isinstance(p, dict):
                continue
            if p.get("client_id") == cid and p.get("status") == "active" and p.get("effect") == "allow":
                has_allow = True
                break
        if has_allow:
            client = c
            break
    if client is None:
        # still record an audit log row? rule says "every get_1password_credentials call must insert exactly one audit row"
        # but schema requires client_id not-null, so if we cannot resolve a client we must return UNAUTHORIZED without writing.
        return _err("UNAUTHORIZED", "No authenticated active client context available")

    client_id = client.get("id")

    # ---- idempotency: if request_id already exists, return the existing outcome instead of error ----
    existing_audit = None
    for a in audits:
        if isinstance(a, dict) and a.get("request_id") == request_id:
            existing_audit = a
            break
    if existing_audit is not None:
        # Return a stable response. Never return secrets from audit (secrets are not stored).
        if existing_audit.get("client_id") != client_id:
            # request_id is globally unique; if collision across clients treat as conflict
            return _err("CONFLICT", "request_id already exists", request_id=request_id)
        decision = existing_audit.get("decision")
        if decision == "allowed":
            return {
                "request_id": request_id,
                "vault_id": existing_audit.get("op_vault_id"),
                "item_id": existing_audit.get("op_item_id"),
                "item_title": existing_audit.get("op_item_title"),
                "fields": existing_audit.get("allowed_fields_effective") or [],
                "credentials": {},  # secrets are never persisted; idempotent replay returns empty materialized secrets
                "session_id": existing_audit.get("session_id"),
                "cached": True
            }
        # denied/error: return the same error code
        code = existing_audit.get("error_code") or ("policy_denied" if decision == "denied" else "upstream_error")
        http_status = existing_audit.get("http_status")
        return _err("CONFLICT" if http_status == 409 else ("RATE_LIMIT" if http_status == 429 else "UNAUTHORIZED" if http_status == 401 else "VALIDATION_ERROR"),
                    "request previously recorded", request_id=request_id, decision=decision, error_code=code)

    # ---- rate limiting / quota (implementation-defined but enforced via audit logs) ----
    # per-client: 60/min and 2000/day, count all decisions
    one_min_ago = now_dt - datetime.timedelta(minutes=1)
    one_day_ago = now_dt - datetime.timedelta(days=1)
    per_min = 0
    per_day = 0
    for a in audits:
        if not isinstance(a, dict) or a.get("client_id") != client_id:
            continue
        adt = _parse_dt(a.get("created_at"))
        if adt is None:
            continue
        if adt >= one_min_ago:
            per_min += 1
        if adt >= one_day_ago:
            per_day += 1
    RATE_PER_MIN = 60
    QUOTA_PER_DAY = 2000
    rate_limited = per_min >= RATE_PER_MIN
    quota_exceeded = per_day >= QUOTA_PER_DAY

    # ---- policy evaluation ----
    # Matching semantics:
    # - policy.vault_id is None => any vault; else must equal request vault_id
    # - if policy.item_id is set, match if request item_id equals it OR if request has only title and policy has title match; we treat item_id policy as stricter to item_id only
    # - if policy.item_title_match is set and request has item_title, match by regex/substr helper
    # A request matches a policy if:
    #   - vault matches AND (
    #       (policy.item_id and request.item_id == policy.item_id) OR
    #       (not policy.item_id and policy.item_title_match and request.item_title matches) OR
    #       (not policy.item_id and not policy.item_title_match and policy.vault_id is not None and request specifies item_id?) -> treat as "any item in vault" when policy specifies vault only
    #     )
    def _policy_matches(p):
        if not isinstance(p, dict):
            return False
        if p.get("client_id") != client_id:
            return False
        if p.get("status") != "active":
            return False
        pv = p.get("vault_id")
        if pv is not None and pv != vault_id:
            return False
        pid = p.get("item_id")
        ptm = p.get("item_title_match")
        # Must have at least one selector non-null per constraints
        if pid is None and pv is None and ptm is None:
            return False
        if pid is not None:
            return item_id is not None and item_id == pid
        if ptm is not None:
            return item_title is not None and _match_title(ptm, item_title)
        # vault-only policy (pv set, pid/ptm null): matches any item in vault
        return pv is not None

    matching_allows = [p for p in policies if _policy_matches(p) and p.get("effect") == "allow"]
    matching_denies = [p for p in policies if _policy_matches(p) and p.get("effect") == "deny"]

    decision = None
    http_status = None
    error_code = None
    allowed_fields_effective = None
    session_id = None
    response = None

    # ---- decide / compute effective fields ----
    if rate_limited or quota_exceeded:
        decision = "denied"
        http_status = 429
        error_code = "rate_limited" if rate_limited else "quota_exceeded"
    elif matching_denies:
        decision = "denied"
        http_status = 403
        error_code = "deny_override"
    elif not matching_allows:
        decision = "denied"
        http_status = 403
        error_code = "policy_denied"
    else:
        # union allowed_fields across all matching allow rules, then intersect with requested
        allowed_union = set()
        for p in matching_allows:
            af = p.get("allowed_fields")
            if isinstance(af, list):
                for f in af:
                    if f in allowed_field_values:
                        allowed_union.add(f)
        allowed_fields_effective = [f for f in req_fields if f in allowed_union]
        if not allowed_fields_effective:
            decision = "denied"
            http_status = 403
            error_code = "no_fields_permitted"
        else:
            decision = "allowed"
            http_status = 200
            error_code = None

    # ---- retrieval session creation/reuse (no secret persistence) ----
    def _fingerprint():
        payload = {
            "client_id": client_id,
            "vault_id": vault_id,
            "item_id": item_id,
            "item_title": item_title,
            "fields": allowed_fields_effective if allowed_fields_effective is not None else []
        }
        raw = json.dumps(payload, sort_keys=True, separators=(",", ":")).encode("utf-8")
        return hashlib.sha256(raw).hexdigest()

    # If allowed, we may create/reuse an active session for fingerprint (unique active per constraint)
    if decision == "allowed":
        fp = _fingerprint()
        # try reuse
        active = None
        for s in sessions:
            if not isinstance(s, dict):
                continue
            if s.get("client_id") != client_id:
                continue
            if s.get("status") != "active":
                continue
            if s.get("request_fingerprint") != fp:
                continue
            exp = _parse_dt(s.get("expires_at"))
            if exp is not None and exp <= now_dt:
                continue
            active = s
            break
        if active is not None:
            session_id = active.get("id")
            active["last_accessed_at"] = now_iso
            active["updated_at"] = now_iso
        else:
            session_id = _gen_id("ops")
            ttl = datetime.timedelta(hours=24)
            expires_at = (now_dt + ttl).isoformat()
            sess_row = {
                "id": session_id,
                "client_id": client_id,
                "request_fingerprint": fp,
                "status": "active",
                "expires_at": expires_at,
                "last_accessed_at": now_iso,
                "failure_reason": None,
                "created_at": now_iso,
                "updated_at": now_iso
            }
            sessions.append(sess_row)

        # "retrieve" secrets from upstream: offline server cannot; return placeholders only for requested keys
        # IMPORTANT: do not persist any of this.
        credentials = {k: None for k in allowed_fields_effective}
        response = {
            "request_id": request_id,
            "vault_id": vault_id,
            "item_id": item_id,
            "item_title": item_title,
            "fields": allowed_fields_effective,
            "credentials": credentials,
            "session_id": session_id,
            "cached": False
        }

    # ---- write exactly one audit log row (unique request_id) ----
    latency_ms = int(max(0, round((time.time() - t0) * 1000)))
    audit_row = {
        "id": _gen_id("opa"),
        "client_id": client_id,
        "session_id": session_id,
        "request_id": request_id,
        "source_ip": None,
        "user_agent": None,
        "op_vault_id": vault_id,
        "op_item_id": item_id,
        "op_item_title": item_title,
        "allowed_fields_effective": allowed_fields_effective if decision == "allowed" else (allowed_fields_effective or [] if decision == "denied" else None),
        "decision": decision if decision is not None else "error",
        "http_status": http_status,
        "error_code": error_code,
        "latency_ms": latency_ms,
        "created_at": now_iso,
        "updated_at": now_iso
    }
    # enforce uniqueness of request_id at insert time: if race, return conflict (but still try to not double-write)
    if any(isinstance(a, dict) and a.get("request_id") == request_id for a in audits):
        return _err("CONFLICT", "request_id already exists", request_id=request_id)

    audits.append(audit_row)

    # update api_clients.last_used_at only on successful allowed call
    if decision == "allowed":
        client["last_used_at"] = now_iso
        client["updated_at"] = now_iso

    # persist changes that occurred
    _save("retrieval_audit_logs.json", audits)
    if decision == "allowed":
        _save("retrieval_sessions.json", sessions)
        _save("api_clients.json", clients)

    if decision == "allowed":
        return response

    # denied path
    if http_status == 429:
        return _err("RATE_LIMIT" if rate_limited else "QUOTA_EXCEEDED", "Request denied due to rate/quota limit", request_id=request_id, error_code=error_code)
    return _err("UNAUTHORIZED" if http_status == 401 else "INVALID_TRANSITION" if http_status == 409 else "CONFLICT" if http_status == 409 else "VALIDATION_ERROR" if http_status == 400 else "UNAUTHORIZED" if http_status == 401 else "CONFLICT" if http_status == 409 else "UNAUTHORIZED" if http_status == 403 else "UNAUTHORIZED",
                "Request denied by policy", request_id=request_id, error_code=error_code)

def get_current_identity(api_key, **_extra):
    import json, os, datetime, time, secrets

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0150000" if __import__("os").path.isdir("./environment_mix/0150000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now_dt = datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0)
    now_iso = now_dt.isoformat()

    def _parse_dt(s):
        if s is None:
            return None
        if isinstance(s, datetime.datetime):
            return s if s.tzinfo else s.replace(tzinfo=datetime.timezone.utc)
        if not isinstance(s, str):
            return None
        ss = s.strip()
        if ss.endswith("Z"):
            ss = ss[:-1] + "+00:00"
        try:
            d = datetime.datetime.fromisoformat(ss)
            return d if d.tzinfo else d.replace(tzinfo=datetime.timezone.utc)
        except Exception:
            return None

    def _gen_id(prefix):
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        return prefix + "_" + "".join(secrets.choice(alphabet) for _ in range(26))

    # Validate
    if not isinstance(api_key, str) or not api_key.strip():
        return _err("VALIDATION_ERROR", "api_key must be a non-empty string")
    api_key = api_key.strip()

    clients = _load("api_clients.json")
    policies = _load("credential_policies.json")
    audits = _load("retrieval_audit_logs.json")

    # Authenticate: vendor contract says compare presented secret to stored api_key_hash constant-time.
    # Datastore does not contain plaintext, so support matching by client-visible value (id or key_prefix)
    # OR direct equality to stored api_key_hash if caller provides that exact stored value.
    authed = None
    for c in clients:
        if not isinstance(c, dict):
            continue
        if c.get("id") == api_key or c.get("key_prefix") == api_key:
            authed = c
            break
        stored = c.get("api_key_hash")
        if isinstance(stored, str) and secrets.compare_digest(stored, api_key):
            authed = c
            break

    # Always append exactly one audit log row for this endpoint call
    request_id = "req_" + secrets.token_hex(16)
    while any(isinstance(a, dict) and a.get("request_id") == request_id for a in audits):
        request_id = "req_" + secrets.token_hex(16)

    audit_row = {
        "id": _gen_id("opa"),
        "client_id": authed.get("id") if isinstance(authed, dict) else "unknown",
        "session_id": None,
        "request_id": request_id,
        "source_ip": None,
        "user_agent": None,
        "op_vault_id": None,
        "op_item_id": None,
        "op_item_title": None,
        "allowed_fields_effective": None,
        "decision": "allowed" if (isinstance(authed, dict) and authed.get("status") == "active") else "denied",
        "http_status": 200 if (isinstance(authed, dict) and authed.get("status") == "active") else 401,
        "error_code": None if (isinstance(authed, dict) and authed.get("status") == "active") else "unauthorized",
        "latency_ms": None,
        "created_at": now_iso,
        "updated_at": now_iso,
    }

    # Rate limit snapshot for response (do not deny identity call; just report state)
    RATE_PER_MIN = 60
    QUOTA_PER_DAY = 2000
    per_min = 0
    per_day = 0
    if isinstance(authed, dict):
        client_id = authed.get("id")
        one_min_ago = now_dt - datetime.timedelta(minutes=1)
        one_day_ago = now_dt - datetime.timedelta(days=1)
        for a in audits:
            if not isinstance(a, dict) or a.get("client_id") != client_id:
                continue
            adt = _parse_dt(a.get("created_at"))
            if adt is None:
                continue
            if adt >= one_min_ago:
                per_min += 1
            if adt >= one_day_ago:
                per_day += 1

    # Finish audit row + persist
    audit_row["latency_ms"] = max(0, int((time.time() - t0) * 1000))
    audits.append(audit_row)
    _save("retrieval_audit_logs.json", audits)

    if authed is None:
        return _err("UNAUTHORIZED", "Invalid API key", request_id=request_id)

    if authed.get("status") != "active":
        # tool description says FORBIDDEN; contract allows UNAUTHORIZED only. Use UNAUTHORIZED consistently.
        return _err("UNAUTHORIZED", "Client is not active", status=authed.get("status"), request_id=request_id)

    # Update last_used_at
    updated = False
    for c in clients:
        if isinstance(c, dict) and c.get("id") == authed.get("id"):
            c["last_used_at"] = now_iso
            c["updated_at"] = now_iso
            updated = True
            break
    if updated:
        _save("api_clients.json", clients)

    client_id = authed.get("id")
    active_allows = []
    for p in policies:
        if not isinstance(p, dict):
            continue
        if p.get("client_id") != client_id:
            continue
        if p.get("status") != "active" or p.get("effect") != "allow":
            continue
        active_allows.append({
            "policy_id": p.get("id"),
            "vault_id": p.get("vault_id"),
            "item_id": p.get("item_id"),
            "item_title_match": p.get("item_title_match"),
            "allowed_fields": p.get("allowed_fields"),
        })

    return {
        "request_id": request_id,
        "client": {
            "id": authed.get("id"),
            "name": authed.get("name"),
            "key_prefix": authed.get("key_prefix"),
            "status": authed.get("status"),
            "last_used_at": authed.get("last_used_at"),
            "created_at": authed.get("created_at"),
            "updated_at": authed.get("updated_at"),
        },
        "effective_scopes": {
            "active_allow_policies": active_allows
        },
        "rate_limit": {
            "per_minute": {"limit": RATE_PER_MIN, "used": per_min, "remaining": max(0, RATE_PER_MIN - per_min)},
            "per_day": {"limit": QUOTA_PER_DAY, "used": per_day, "remaining": max(0, QUOTA_PER_DAY - per_day)},
        },
    }

def list_credential_policies(api_key, status=None, effect=None, vault_id=None, item_id=None, item_title_match=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, time, secrets, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0150000" if __import__("os").path.isdir("./environment_mix/0150000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now_dt = datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0)
    now_iso = now_dt.isoformat()

    def _parse_dt(s):
        if s is None:
            return None
        if isinstance(s, datetime.datetime):
            return s if s.tzinfo else s.replace(tzinfo=datetime.timezone.utc)
        if not isinstance(s, str):
            return None
        ss = s.strip()
        if ss.endswith("Z"):
            ss = ss[:-1] + "+00:00"
        try:
            d = datetime.datetime.fromisoformat(ss)
            return d if d.tzinfo else d.replace(tzinfo=datetime.timezone.utc)
        except Exception:
            return None

    def _gen_cursor(last_id):
        payload = json.dumps({"after": last_id}, separators=(",", ":"), ensure_ascii=False).encode("utf-8")
        return base64.urlsafe_b64encode(payload).decode("ascii").rstrip("=")

    def _parse_cursor(cur):
        if cur is None:
            return None
        if not isinstance(cur, str) or not cur.strip():
            return _err("VALIDATION_ERROR", "cursor must be a non-empty string when provided")
        s = cur.strip()
        pad = "=" * (-len(s) % 4)
        try:
            obj = json.loads(base64.urlsafe_b64decode((s + pad).encode("ascii")).decode("utf-8"))
        except Exception:
            return _err("VALIDATION_ERROR", "cursor is invalid")
        after = obj.get("after")
        if not isinstance(after, str) or not after:
            return _err("VALIDATION_ERROR", "cursor is invalid")
        return after

    # Validate inputs
    if not isinstance(api_key, str) or not api_key.strip():
        return _err("VALIDATION_ERROR", "api_key must be a non-empty string")
    api_key = api_key.strip()

    if status is not None and status not in ("active", "disabled"):
        return _err("VALIDATION_ERROR", "status must be 'active' or 'disabled'")
    if effect is not None and effect not in ("allow", "deny"):
        return _err("VALIDATION_ERROR", "effect must be 'allow' or 'deny'")
    if vault_id is not None and (not isinstance(vault_id, str) or not vault_id.strip()):
        return _err("VALIDATION_ERROR", "vault_id must be a non-empty string when provided")
    if item_id is not None and (not isinstance(item_id, str) or not item_id.strip()):
        return _err("VALIDATION_ERROR", "item_id must be a non-empty string when provided")
    if item_title_match is not None and (not isinstance(item_title_match, str) or not item_title_match.strip()):
        return _err("VALIDATION_ERROR", "item_title_match must be a non-empty string when provided")

    vault_id = vault_id.strip() if isinstance(vault_id, str) else None
    item_id = item_id.strip() if isinstance(item_id, str) else None
    item_title_match = item_title_match.strip() if isinstance(item_title_match, str) else None

    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit < 1 or limit > 200:
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 200")

    after_id = None
    pc = _parse_cursor(cursor)
    if isinstance(pc, dict) and pc.get("error"):
        return pc
    after_id = pc

    clients = _load("api_clients.json")
    policies = _load("credential_policies.json")
    audits = _load("retrieval_audit_logs.json")

    # Authenticate (same rule as identity: accept id/key_prefix or exact stored api_key_hash match)
    authed = None
    for c in clients:
        if not isinstance(c, dict):
            continue
        if c.get("id") == api_key or c.get("key_prefix") == api_key:
            authed = c
            break
        stored = c.get("api_key_hash")
        if isinstance(stored, str) and secrets.compare_digest(stored, api_key):
            authed = c
            break
    if authed is None:
        return _err("UNAUTHORIZED", "Invalid API key")
    if authed.get("status") != "active":
        return _err("UNAUTHORIZED", "Client is not active", status=authed.get("status"))

    client_id = authed.get("id")

    # Update last_used_at
    for c in clients:
        if isinstance(c, dict) and c.get("id") == client_id:
            c["last_used_at"] = now_iso
            c["updated_at"] = now_iso
            break
    _save("api_clients.json", clients)

    # Filter + sort (stable by created_at desc then id)
    filtered = []
    for p in policies:
        if not isinstance(p, dict):
            continue
        if p.get("client_id") != client_id:
            continue
        if status is not None and p.get("status") != status:
            continue
        if effect is not None and p.get("effect") != effect:
            continue
        if vault_id is not None and p.get("vault_id") != vault_id:
            continue
        if item_id is not None and p.get("item_id") != item_id:
            continue
        if item_title_match is not None and p.get("item_title_match") != item_title_match:
            continue
        filtered.append(p)

    def _sort_key(p):
        dt = _parse_dt(p.get("created_at")) or datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc)
        return (-int(dt.timestamp()), str(p.get("id") or ""))

    filtered.sort(key=_sort_key)

    # Pagination by "after id" in this ordering
    start = 0
    if after_id is not None:
        for i, p in enumerate(filtered):
            if p.get("id") == after_id:
                start = i + 1
                break

    page = filtered[start:start + limit]
    has_more = (start + limit) < len(filtered)
    next_cursor = _gen_cursor(page[-1].get("id")) if (has_more and page) else None

    # Observe service dynamics: log the call
    request_id = "req_" + secrets.token_hex(16)
    while any(isinstance(a, dict) and a.get("request_id") == request_id for a in audits):
        request_id = "req_" + secrets.token_hex(16)

    def _gen_id(prefix):
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        return prefix + "_" + "".join(secrets.choice(alphabet) for _ in range(26))

    audit_row = {
        "id": _gen_id("opa"),
        "client_id": client_id,
        "session_id": None,
        "request_id": request_id,
        "source_ip": None,
        "user_agent": None,
        "op_vault_id": None,
        "op_item_id": None,
        "op_item_title": None,
        "allowed_fields_effective": None,
        "decision": "allowed",
        "http_status": 200,
        "error_code": None,
        "latency_ms": max(0, int((time.time() - t0) * 1000)),
        "created_at": now_iso,
        "updated_at": now_iso,
    }
    audits.append(audit_row)
    _save("retrieval_audit_logs.json", audits)

    return {
        "request_id": request_id,
        "data": page,
        "pagination": {
            "limit": limit,
            "total": len(filtered),
            "has_more": has_more,
            "next_cursor": next_cursor,
        },
    }

def create_credential_policy(api_key, vault_id, effect, item_id=None, item_title_match=None, allowed_fields=None, status=None, **_extra):
    import json, os, datetime, time, secrets

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0150000" if __import__("os").path.isdir("./environment_mix/0150000") else "/app/database")
