            return _err("VALIDATION_ERROR", "item_title_match must be a non-empty string when provided")
        item_title_match = item_title_match.strip()

    if status is None:
        status = "active"
    if status not in ("active", "disabled"):
        return _err("VALIDATION_ERROR", "status must be 'active' or 'disabled'")

    # Business constraint: at least one of (vault_id, item_id, item_title_match) non-null.
    # vault_id is required by tool, so always satisfied.

    allowed_field_values = {"username", "password", "url", "totp", "notes", "custom_fields"}
    norm_allowed_fields = None
    if allowed_fields is not None:
        if not isinstance(allowed_fields, list):
            return _err("VALIDATION_ERROR", "allowed_fields must be an array when provided")
        uniq = []
        seen = set()
        for f in allowed_fields:
            if not isinstance(f, str):
                return _err("VALIDATION_ERROR", "allowed_fields entries must be strings")
            if f not in allowed_field_values:
                return _err("VALIDATION_ERROR", "allowed_fields contains an invalid value", value=f)
            if f not in seen:
                uniq.append(f)
                seen.add(f)
        norm_allowed_fields = uniq

    # Enforce: allowed_fields must be non-empty for allow policies.
    if effect == "allow":
        if norm_allowed_fields is None or len(norm_allowed_fields) == 0:
            return _err("VALIDATION_ERROR", "Business rule: allowed_fields must be non-empty for effect='allow'")
    else:
        # For deny, allowed_fields may be omitted; store [] to satisfy non-null schema.
        if norm_allowed_fields is None:
            norm_allowed_fields = []

    clients = _load("api_clients.json")
    policies = _load("credential_policies.json")

    # Authenticate (accept id/key_prefix or exact stored api_key_hash match)
    authed = None
    for c in clients:
        if not isinstance(c, dict):
            continue
        if c.get("id") == api_key or c.get("key_prefix") == api_key:
            authed = c
            break
        stored = c.get("api_key_hash")
        if isinstance(stored, str) and secrets.compare_digest(stored, api_key):
            authed = c
            break
    if authed is None:
        return _err("UNAUTHORIZED", "Invalid API key")
    if authed.get("status") != "active":
        return _err("UNAUTHORIZED", "Client is not active", status=authed.get("status"))

    client_id = authed.get("id")

    # Uniqueness constraint: unique(client_id, vault_id, item_id, item_title_match, effect) where status='active'
    if status == "active":
        for p in policies:
            if not isinstance(p, dict):
                continue
            if p.get("status") != "active":
                continue
            if p.get("client_id") != client_id:
                continue
            if p.get("effect") != effect:
                continue
            if (p.get("vault_id") == vault_id and p.get("item_id") == item_id and p.get("item_title_match") == item_title_match):
                return _err("CONFLICT", "Active policy with same match criteria and effect already exists", policy_id=p.get("id"))

    # Create row
    new_id = _gen_id("opp")
    while any(isinstance(p, dict) and p.get("id") == new_id for p in policies):
        new_id = _gen_id("opp")

    row = {
        "id": new_id,
        "client_id": client_id,
        "vault_id": vault_id,
        "item_id": item_id,
        "item_title_match": item_title_match,
        "allowed_fields": norm_allowed_fields,
        "effect": effect,
        "status": status,
        "created_at": now_iso,
        "updated_at": now_iso,
    }

    policies.append(row)
    _save("credential_policies.json", policies)

    # Update last_used_at
    for c in clients:
        if isinstance(c, dict) and c.get("id") == client_id:
            c["last_used_at"] = now_iso
            c["updated_at"] = now_iso
            break
    _save("api_clients.json", clients)

    return {"data": row, "latency_ms": max(0, int((time.time() - t0) * 1000))}

