    if effect is not None and effect not in ("allow", "deny"):
        return _err("VALIDATION_ERROR", "effect must be 'allow' or 'deny' when provided")
    if status is not None and status not in ("active", "disabled"):
        return _err("VALIDATION_ERROR", "status must be 'active' or 'disabled' when provided")

    allowed_field_values = {"username", "password", "url", "totp", "notes", "custom_fields"}
    norm_allowed_fields = None
    if allowed_fields is not None:
        if not isinstance(allowed_fields, list):
            return _err("VALIDATION_ERROR", "allowed_fields must be an array when provided")
        uniq = []
        seen = set()
        for f in allowed_fields:
            if not isinstance(f, str):
                return _err("VALIDATION_ERROR", "allowed_fields entries must be strings")
            if f not in allowed_field_values:
                return _err("VALIDATION_ERROR", "allowed_fields contains an invalid value", value=f)
            if f not in seen:
                uniq.append(f)
                seen.add(f)
        norm_allowed_fields = uniq

    clients = _load("api_clients.json")
    policies = _load("credential_policies.json")

    # Authenticate
    authed = None
    for c in clients:
        if not isinstance(c, dict):
            continue
        if c.get("id") == api_key or c.get("key_prefix") == api_key:
            authed = c
            break
        stored = c.get("api_key_hash")
        if isinstance(stored, str) and secrets.compare_digest(stored, api_key):
            authed = c
            break
    if authed is None:
        return _err("UNAUTHORIZED", "Invalid API key")
    if authed.get("status") != "active":
        return _err("UNAUTHORIZED", "Client is not active", status=authed.get("status"))
    client_id = authed.get("id")

    # Locate policy
    target = None
    for p in policies:
        if isinstance(p, dict) and p.get("id") == policy_id and p.get("client_id") == client_id:
            target = p
            break
    if target is None:
        return _err("NOT_FOUND", "Policy not found")

    # Apply lifecycle transition rule
    if status is not None and status != target.get("status"):
        transitions = {"active": {"disabled"}, "disabled": {"active"}}
        cur = target.get("status")
        if cur not in transitions or status not in transitions[cur]:
            return _err("INVALID_TRANSITION", "Requested status transition is not allowed", from_status=cur, to_status=status)

    new_effect = effect if effect is not None else target.get("effect")
    new_vault_id = vault_id if vault_id is not None else target.get("vault_id")
    new_item_id = item_id if item_id is not None else target.get("item_id")
    new_item_title_match = item_title_match if item_title_match is not None else target.get("item_title_match")
    new_status = status if status is not None else target.get("status")

    # Ensure match constraint still holds: at least one of (vault_id, item_id, item_title_match) non-null
    if new_vault_id is None and new_item_id is None and new_item_title_match is None:
        return _err("VALIDATION_ERROR", "Business rule: at least one of vault_id, item_id, item_title_match must be provided")

    # allowed_fields rules
    if norm_allowed_fields is not None:
        new_allowed_fields = norm_allowed_fields
    else:
        new_allowed_fields = target.get("allowed_fields")

    if new_effect == "allow":
        if not isinstance(new_allowed_fields, list) or len(new_allowed_fields) == 0:
            return _err("VALIDATION_ERROR", "Business rule: allowed_fields must be non-empty for effect='allow'")
    else:
        # For deny, allowed_fields must be non-null per schema; default to [] if missing/None
        if new_allowed_fields is None:
            new_allowed_fields = []
        if not isinstance(new_allowed_fields, list):
            return _err("VALIDATION_ERROR", "allowed_fields must be an array when provided")

    # Uniqueness constraint for active policies (excluding self)
    if new_status == "active":
        for p in policies:
            if not isinstance(p, dict) or p is target:
                continue
            if p.get("status") != "active":
                continue
            if p.get("client_id") != client_id:
                continue
            if p.get("effect") != new_effect:
                continue
            if (p.get("vault_id") == new_vault_id and p.get("item_id") == new_item_id and p.get("item_title_match") == new_item_title_match):
                return _err("CONFLICT", "Active policy with same match criteria and effect already exists", policy_id=p.get("id"))

    # Mutate + persist
    changed = False
    for k, v in (("vault_id", new_vault_id), ("item_id", new_item_id), ("item_title_match", new_item_title_match),
                ("allowed_fields", new_allowed_fields), ("effect", new_effect), ("status", new_status)):
        if target.get(k) != v:
            target[k] = v
            changed = True

    if not changed:
        # Idempotent: return current row, but this is still a "mutation" call; it matched a row.
        # Keep updated_at unchanged to reflect no change.
        return {"data": target, "latency_ms": max(0, int((time.time() - t0) * 1000)), "idempotent": True}

    target["updated_at"] = now_iso
    _save("credential_policies.json", policies)

    # Update client last_used_at
    for c in clients:
        if isinstance(c, dict) and c.get("id") == client_id:
            c["last_used_at"] = now_iso
            c["updated_at"] = now_iso
            break
    _save("api_clients.json", clients)

    return {"data": target, "latency_ms": max(0, int((time.time() - t0) * 1000))}

def list_retrieval_audit_logs(api_key, decision=None, request_id=None, session_id=None, vault_id=None, item_id=None, from_created_at=None, to_created_at=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, time, secrets, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0150000" if __import__("os").path.isdir("./environment_mix/0150000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now_dt = datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0)
    now_iso = now_dt.isoformat()

    def _parse_dt(s):
        if s is None:
            return None
        if isinstance(s, datetime.datetime):
            return s if s.tzinfo else s.replace(tzinfo=datetime.timezone.utc)
        if not isinstance(s, str):
            return None
        ss = s.strip()
        if ss.endswith("Z"):
            ss = ss[:-1] + "+00:00"
        try:
            d = datetime.datetime.fromisoformat(ss)
            return d if d.tzinfo else d.replace(tzinfo=datetime.timezone.utc)
        except Exception:
            return None

    def _gen_cursor(last_id):
        payload = json.dumps({"after": last_id}, separators=(",", ":"), ensure_ascii=False).encode("utf-8")
        return base64.urlsafe_b64encode(payload).decode("ascii").rstrip("=")

    def _parse_cursor(cur):
        if cur is None:
            return None
        if not isinstance(cur, str) or not cur.strip():
            return _err("VALIDATION_ERROR", "cursor must be a non-empty string when provided")
        s = cur.strip()
        pad = "=" * (-len(s) % 4)
        try:
            obj = json.loads(base64.urlsafe_b64decode((s + pad).encode("ascii")).decode("utf-8"))
        except Exception:
            return _err("VALIDATION_ERROR", "cursor is invalid")
        after = obj.get("after")
        if not isinstance(after, str) or not after:
            return _err("VALIDATION_ERROR", "cursor is invalid")
        return after

    # Validate inputs
    if not isinstance(api_key, str) or not api_key.strip():
        return _err("VALIDATION_ERROR", "api_key must be a non-empty string")
    api_key = api_key.strip()

    if decision is not None and decision not in ("allowed", "denied", "error"):
        return _err("VALIDATION_ERROR", "decision must be 'allowed', 'denied', or 'error'")
    if request_id is not None and (not isinstance(request_id, str) or not request_id.strip()):
        return _err("VALIDATION_ERROR", "request_id must be a non-empty string when provided")
    if session_id is not None and (not isinstance(session_id, str) or not session_id.strip()):
        return _err("VALIDATION_ERROR", "session_id must be a non-empty string when provided")
    if vault_id is not None and (not isinstance(vault_id, str) or not vault_id.strip()):
        return _err("VALIDATION_ERROR", "vault_id must be a non-empty string when provided")
    if item_id is not None and (not isinstance(item_id, str) or not item_id.strip()):
        return _err("VALIDATION_ERROR", "item_id must be a non-empty string when provided")

    request_id = request_id.strip() if isinstance(request_id, str) else None
    session_id = session_id.strip() if isinstance(session_id, str) else None
    vault_id = vault_id.strip() if isinstance(vault_id, str) else None
    item_id = item_id.strip() if isinstance(item_id, str) else None

    from_dt = None
    to_dt = None
    if from_created_at is not None:
        if not isinstance(from_created_at, str) or not from_created_at.strip():
            return _err("VALIDATION_ERROR", "from_created_at must be an RFC3339 timestamp string when provided")
        from_dt = _parse_dt(from_created_at)
        if from_dt is None:
            return _err("VALIDATION_ERROR", "from_created_at must be an RFC3339 timestamp", value=from_created_at)
    if to_created_at is not None:
        if not isinstance(to_created_at, str) or not to_created_at.strip():
            return _err("VALIDATION_ERROR", "to_created_at must be an RFC3339 timestamp string when provided")
        to_dt = _parse_dt(to_created_at)
        if to_dt is None:
            return _err("VALIDATION_ERROR", "to_created_at must be an RFC3339 timestamp", value=to_created_at)
    if from_dt and to_dt and to_dt < from_dt:
        return _err("VALIDATION_ERROR", "to_created_at must be >= from_created_at")

    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit < 1 or limit > 200:
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 200")

    after_id = None
    pc = _parse_cursor(cursor)
    if isinstance(pc, dict) and pc.get("error"):
        return pc
    after_id = pc

    clients = _load("api_clients.json")
    audits = _load("retrieval_audit_logs.json")

    # Authenticate
    authed = None
    for c in clients:
        if not isinstance(c, dict):
            continue
        if c.get("id") == api_key or c.get("key_prefix") == api_key:
            authed = c
            break
        stored = c.get("api_key_hash")
        if isinstance(stored, str) and secrets.compare_digest(stored, api_key):
            authed = c
            break
    if authed is None:
        return _err("UNAUTHORIZED", "Invalid API key")
    if authed.get("status") != "active":
        return _err("UNAUTHORIZED", "Client is not active", status=authed.get("status"))
    client_id = authed.get("id")

    # Update last_used_at
    for c in clients:
        if isinstance(c, dict) and c.get("id") == client_id:
            c["last_used_at"] = now_iso
            c["updated_at"] = now_iso
            break
    _save("api_clients.json", clients)

    # Filter
    filtered = []
    for a in audits:
        if not isinstance(a, dict):
            continue
        if a.get("client_id") != client_id:
            continue
        if decision is not None and a.get("decision") != decision:
            continue
        if request_id is not None and a.get("request_id") != request_id:
            continue
        if session_id is not None and a.get("session_id") != session_id:
            continue
        if vault_id is not None and a.get("op_vault_id") != vault_id:
            continue
        if item_id is not None and a.get("op_item_id") != item_id:
            continue
        adt = _parse_dt(a.get("created_at"))
        if from_dt is not None and (adt is None or adt < from_dt):
            continue
        if to_dt is not None and (adt is None or adt > to_dt):
            continue
        filtered.append(a)

    # Sort by created_at desc, id asc
    def _sort_key(a):
        dt = _parse_dt(a.get("created_at")) or datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc)
        return (-int(dt.timestamp()), str(a.get("id") or ""))

    filtered.sort(key=_sort_key)

    # Paginate
    start = 0
    if after_id is not None:
        for i, a in enumerate(filtered):
            if a.get("id") == after_id:
                start = i + 1
                break
    page = filtered[start:start + limit]
    has_more = (start + limit) < len(filtered)
    next_cursor = _gen_cursor(page[-1].get("id")) if (has_more and page) else None

    # Observe service dynamics: log this listing call too (but do NOT include secrets; none here)
    def _gen_id(prefix):
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        return prefix + "_" + "".join(secrets.choice(alphabet) for _ in range(26))

    reqid = "req_" + secrets.token_hex(16)
    while any(isinstance(x, dict) and x.get("request_id") == reqid for x in audits):
        reqid = "req_" + secrets.token_hex(16)

    audits.append({
        "id": _gen_id("opa"),
        "client_id": client_id,
        "session_id": None,
        "request_id": reqid,
        "source_ip": None,
        "user_agent": None,
        "op_vault_id": None,
        "op_item_id": None,
        "op_item_title": None,
        "allowed_fields_effective": None,
        "decision": "allowed",
        "http_status": 200,
        "error_code": None,
        "latency_ms": max(0, int((time.time() - t0) * 1000)),
        "created_at": now_iso,
        "updated_at": now_iso,
    })
    _save("retrieval_audit_logs.json", audits)

    return {
        "request_id": reqid,
        "data": page,
        "pagination": {
            "limit": limit,
            "total": len(filtered),
            "has_more": has_more,
            "next_cursor": next_cursor,
        },
    }

def update_retrieval_session(api_key, session_id, status, failure_reason=None, **_extra):
    import json, os, datetime, time, secrets

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0150000" if __import__("os").path.isdir("./environment_mix/0150000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now_dt = datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0)
    now_iso = now_dt.isoformat()

    def _parse_dt(s):
        if s is None:
            return None
        if isinstance(s, datetime.datetime):
            return s if s.tzinfo else s.replace(tzinfo=datetime.timezone.utc)
        if not isinstance(s, str):
            return None
        ss = s.strip()
        if ss.endswith("Z"):
            ss = ss[:-1] + "+00:00"
        try:
            d = datetime.datetime.fromisoformat(ss)
            return d if d.tzinfo else d.replace(tzinfo=datetime.timezone.utc)
        except Exception:
            return None

    # Validate inputs
    if not isinstance(api_key, str) or not api_key.strip():
        return _err("VALIDATION_ERROR", "api_key must be a non-empty string")
    api_key = api_key.strip()

    if not isinstance(session_id, str) or not session_id.strip():
        return _err("VALIDATION_ERROR", "session_id must be a non-empty string")
    session_id = session_id.strip()

    if status not in ("active", "expired", "revoked", "failed"):
        return _err("VALIDATION_ERROR", "status must be one of: active, expired, revoked, failed")

    if failure_reason is not None:
        if not isinstance(failure_reason, str) or not failure_reason.strip():
            return _err("VALIDATION_ERROR", "failure_reason must be a non-empty string when provided")
        failure_reason = failure_reason.strip()
        if len(failure_reason) > 500:
            return _err("VALIDATION_ERROR", "failure_reason too long (max 500 chars)")

    clients = _load("api_clients.json")
    sessions = _load("retrieval_sessions.json")

    # Authenticate
    authed = None
    for c in clients:
        if not isinstance(c, dict):
            continue
        if c.get("id") == api_key or c.get("key_prefix") == api_key:
            authed = c
            break
        stored = c.get("api_key_hash")
        if isinstance(stored, str) and secrets.compare_digest(stored, api_key):
            authed = c
            break
    if authed is None:
        return _err("UNAUTHORIZED", "Invalid API key")
    if authed.get("status") != "active":
        return _err("UNAUTHORIZED", "Client is not active", status=authed.get("status"))
    client_id = authed.get("id")

    # Find session
    sess = None
    for s in sessions:
        if isinstance(s, dict) and s.get("id") == session_id and s.get("client_id") == client_id:
            sess = s
            break
    if sess is None:
        return _err("NOT_FOUND", "Session not found")

    # Enforce expiry-based transition rule: after expires_at it may only transition to expired
    expires_at = _parse_dt(sess.get("expires_at"))
    if expires_at is not None and now_dt >= expires_at:
        if status != "expired":
            return _err("INVALID_TRANSITION", "Session is past expires_at; only transition to 'expired' is allowed", expires_at=sess.get("expires_at"))
        # If already expired/revoked/failed, do not allow illegal "change" either
        if sess.get("status") != "active" and sess.get("status") != "failed":
            if sess.get("status") == "expired":
                return {"data": sess, "idempotent": True, "latency_ms": max(0, int((time.time() - t0) * 1000))}
            return _err("INVALID_TRANSITION", "Cannot transition non-active session after expiration window", from_status=sess.get("status"), to_status=status)

    # Lifecycle transitions per schema
    transitions = {
        "active": {"expired", "revoked", "failed"},
        "failed": {"expired"},
        "expired": set(),
        "revoked": set(),
    }
    cur = sess.get("status")
    if cur != status:
        if cur not in transitions or status not in transitions[cur]:
            return _err("INVALID_TRANSITION", "Requested status transition is not allowed", from_status=cur, to_status=status)

    if status == "failed":
        if failure_reason is None:
            return _err("VALIDATION_ERROR", "failure_reason is required when transitioning to status='failed'")
        # sanitized: ensure no obvious secret material patterns (best-effort)
        lower = failure_reason.lower()
        if "password" in lower or "totp" in lower or "private key" in lower:
            return _err("VALIDATION_ERROR", "failure_reason must not include secret material")
    else:
        if failure_reason is not None:
            # Only allow setting failure_reason when failed
            return _err("VALIDATION_ERROR", "failure_reason may only be provided when status='failed'")

    # Mutate; enforce "no success without effect" by returning NOT_FOUND only when missing (handled above).
    changed = False
    if sess.get("status") != status:
        sess["status"] = status
        changed = True
    if status == "failed":
        if sess.get("failure_reason") != failure_reason:
            sess["failure_reason"] = failure_reason
            changed = True
    else:
        if sess.get("failure_reason") is not None:
            sess["failure_reason"] = None
            changed = True

    if not changed:
        return {"data": sess, "idempotent": True, "latency_ms": max(0, int((time.time() - t0) * 1000))}

    sess["updated_at"] = now_iso
    _save("retrieval_sessions.json", sessions)

    # Update client last_used_at
    for c in clients:
        if isinstance(c, dict) and c.get("id") == client_id:
            c["last_used_at"] = now_iso
            c["updated_at"] = now_iso
            break
    _save("api_clients.json", clients)

    return {"data": sess, "latency_ms": max(0, int((time.time() - t0) * 1000))}
